solution:
def normalize_path(path):
    stack = []                                # the names accepted so far, from the root down
    for segment in path.split("/"):
        if segment in ("", "."):
            continue                          # a repeated slash, or "here"
        if segment == "..":
            if stack:
                stack.pop()                   # at the root there is nothing above to go to
        else:
            stack.append(segment)
    result = "/" + "/".join(stack)
    if stack and path.endswith("/"):
        result += "/"                         # keep the trailing slash, except for the root
    return result
